import type { MetadataRoute } from 'next';
import { VARIANTS } from '@/lib/variants';

// Originally generated by .claude/scripts/lib/emit-sitemap.py during bootstrap
// state-11c post-fan-out (#1387). The static list below is still that output
// and should be regenerated when experiment.yaml behaviors change.
//
// The /v/<variant> entries are NOT regenerated, deliberately. The generator
// enumerates dynamic routes from behaviors[*].dynamic_segments, and the A/B
// variants are not declared there — they live under the top-level `variants:`
// key, which it does not read. So it emitted a single placeholder fixture slug,
// `demo-fixture-variant`, which 404s, while all three real variants were
// missing. That shipped to Google Search Console: the sitemap told crawlers to
// fetch a page that does not exist and never mentioned the three pages the paid
// ad campaign points at (experiment/ads.yaml).
//
// Deriving them from VARIANTS instead ties the sitemap to the same array
// src/app/v/[variant]/page.tsx uses in generateStaticParams, so a slug cannot
// appear in one and not the other. Adding or renaming a variant updates both.
// If the generator is ever taught to read `variants:`, this can go back to
// being fully generated.

function base() {
  return process.env.NEXT_PUBLIC_SITE_URL ?? '';
}

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();
  const b = base();
  return [
    { url: `${b}/`, lastModified: now, changeFrequency: 'weekly' as const, priority: 1.0 },
    { url: `${b}/dashboard`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/guides/edited-pdf`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/guides/fake-bank-statement`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/guides/fake-pay-stub`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/login`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/pricing`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/auth/reset-password`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/scan-result`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/signup`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    { url: `${b}/terms`, lastModified: now, changeFrequency: 'weekly' as const, priority: 0.7 },
    ...VARIANTS.map((v) => ({
      url: `${b}/v/${v.slug}`,
      lastModified: now,
      changeFrequency: 'weekly' as const,
      priority: 0.7,
    })),
  ];
}
